import{_ as t,o as d,c as o,a0 as a}from"./chunks/framework.DoRPXVp_.js";const p=JSON.parse('{"title":"CI/CD Workflow Analysis","description":"","frontmatter":{},"headers":[],"relativePath":"ci-cd-reference.md","filePath":"ci-cd-reference.md"}'),i={name:"ci-cd-reference.md"};function l(r,e,s,c,n,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="ci-cd-workflow-analysis" tabindex="-1">CI/CD Workflow Analysis <a class="header-anchor" href="#ci-cd-workflow-analysis" aria-label="Permalink to &quot;CI/CD Workflow Analysis&quot;">​</a></h1><h2 id="workflow-overview" tabindex="-1">Workflow Overview <a class="header-anchor" href="#workflow-overview" aria-label="Permalink to &quot;Workflow Overview&quot;">​</a></h2><p>The project has <strong>8 GitHub Actions workflows</strong>:</p><table tabindex="0"><thead><tr><th>Workflow</th><th>Trigger</th><th>Purpose</th></tr></thead><tbody><tr><td><code>lint.yml</code></td><td>PR, push</td><td>golangci-lint</td></tr><tr><td><code>build-and-deploy.yml</code></td><td>PR with label, push to master</td><td>Unit tests → build/push images → deploy to self-hosted K3s</td></tr><tr><td><code>e2e.yml</code></td><td>Push to dev, PR with <code>run-e2e</code> label</td><td>Build images → setup k3d → deploy → run E2E tests</td></tr><tr><td><code>release.yml</code></td><td>Tag <code>v*</code>, PR with <code>ok-release</code> label</td><td>GoReleaser binaries + Docker image (latticed only)</td></tr><tr><td><code>build-k3s-image.yml</code></td><td>Changes to k3s/deploy paths</td><td>Build + smoke test lattice-k3s image</td></tr><tr><td><code>test-script.yml</code></td><td>PR against master/main</td><td>Validate README CLI commands end-to-end</td></tr><tr><td><code>docs.yml</code></td><td>Push to master (docs path)</td><td>Build VitePress docs → deploy to alatticeio.github.io</td></tr><tr><td><code>pages.yml</code></td><td>Release published, manual</td><td>Build RPM/APT repo indexes on gh-pages branch</td></tr></tbody></table><hr><h2 id="release-pipeline-release-yml" tabindex="-1">Release Pipeline (<code>release.yml</code>) <a class="header-anchor" href="#release-pipeline-release-yml" aria-label="Permalink to &quot;Release Pipeline (`release.yml`)&quot;">​</a></h2><h3 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h3><ol><li><strong>GoReleaser</strong> — Builds binaries for <code>lattice</code> (linux/darwin/windows, amd64/arm64) and <code>latticed</code> (linux, amd64/arm64), creates archives, RPM/DEB packages, Homebrew formula, and publishes a GitHub Release with changelog.</li><li><strong>Docker</strong> — Builds and pushes <code>latticed</code> Docker image (community edition) to GHCR with multi-arch support (linux/amd64, linux/arm64).</li></ol><h3 id="what-s-missing-for-a-complete-release" tabindex="-1">What&#39;s missing for a complete release <a class="header-anchor" href="#what-s-missing-for-a-complete-release" aria-label="Permalink to &quot;What&#39;s missing for a complete release&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Gap</th><th>Impact</th><th>Status</th></tr></thead><tbody><tr><td><strong>No Pro binaries</strong> in GoReleaser</td><td>Pro customers can&#39;t download Pro binaries from GitHub Releases</td><td>✅ Fixed — <code>lattice-pro</code> + <code>latticed-pro</code> builds with <code>-tags pro</code> added</td></tr><tr><td><strong>No Pro Docker images</strong></td><td>Pro customers can&#39;t deploy <code>latticed:latest-pro</code></td><td>✅ Fixed — matrix build in <code>release.yml</code> builds Pro + community for both services</td></tr><tr><td><strong>No <code>lattice</code> agent Docker image</strong></td><td>Agent Docker image not published on release</td><td>✅ Fixed — <code>lattice</code> community + Pro images added to matrix</td></tr><tr><td><strong>No <code>manager</code> Docker image</strong></td><td>K8s operator image not published on release</td><td>❌ Not needed — manager is K8s-only, deployed via kustomize</td></tr><tr><td><strong>No Helm chart publishing</strong></td><td>Helm users can&#39;t install via <code>helm install</code></td><td>❌ Open — not yet scoped</td></tr><tr><td><strong>Package repo not updated</strong></td><td><code>pages.yml</code> runs independently, not chained from release</td><td>❌ Open — requires workflow chaining</td></tr></tbody></table><hr><h2 id="ci-cd-pipeline-build-and-deploy-yml" tabindex="-1">CI/CD Pipeline (<code>build-and-deploy.yml</code>) <a class="header-anchor" href="#ci-cd-pipeline-build-and-deploy-yml" aria-label="Permalink to &quot;CI/CD Pipeline (`build-and-deploy.yml`)&quot;">​</a></h2><p>Builds and pushes <code>latest</code> (on master push) or <code>pr-N</code> tags for <code>latticed</code> and <code>lattice</code> images. Then deploys PR images to a self-hosted K3s server.</p><p><strong>Note:</strong> Only community edition — no Pro build in this pipeline.</p><hr><h2 id="e2e-pipeline-e2e-yml" tabindex="-1">E2E Pipeline (<code>e2e.yml</code>) <a class="header-anchor" href="#e2e-pipeline-e2e-yml" aria-label="Permalink to &quot;E2E Pipeline (`e2e.yml`)&quot;">​</a></h2><p>The most comprehensive pipeline. Supports:</p><ul><li><strong>Community</strong> builds (default)</li><li><strong>Pro</strong> builds (when <code>run-pro</code> label is set on PR or <code>[run-pro]</code> in dev commit message)</li><li>Builds both <code>latticed</code> and <code>lattice</code> images for each edition</li><li>Deploys to k3d, runs full E2E test suite</li><li>Collects diagnostic logs on failure</li></ul><hr><h2 id="other-workflows" tabindex="-1">Other Workflows <a class="header-anchor" href="#other-workflows" aria-label="Permalink to &quot;Other Workflows&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Workflow</th><th>Notes</th></tr></thead><tbody><tr><td><code>lint.yml</code></td><td>Runs on every PR/push — no issues</td></tr><tr><td><code>build-k3s-image.yml</code></td><td>Builds all-in-one K3s image with smoke tests</td></tr><tr><td><code>test-script.yml</code></td><td>Validates README CLI commands against live containers</td></tr><tr><td><code>docs.yml</code></td><td>Deploys VitePress docs site</td></tr><tr><td><code>pages.yml</code></td><td>Builds APT/RPM repo metadata on <code>gh-pages</code> branch</td></tr></tbody></table><hr><h2 id="release-readiness-checklist" tabindex="-1">Release Readiness Checklist <a class="header-anchor" href="#release-readiness-checklist" aria-label="Permalink to &quot;Release Readiness Checklist&quot;">​</a></h2><p>Before cutting a release, verify these are in place:</p><ul><li>[ ] <code>.goreleaser.yaml</code> includes Pro builds (<code>-tags pro</code>) for <code>lattice</code> and <code>latticed</code></li><li>[ ] <code>release.yml</code> builds + pushes Pro Docker images (<code>EDITION=pro</code>)</li><li>[ ] <code>release.yml</code> builds + pushes <code>lattice</code> agent Docker image (not just <code>latticed</code>)</li><li>[ ] Helm chart is published (manual <code>helm package</code> + gh-pages, or automated in CI)</li><li>[ ] Package repo index is refreshed (make <code>pages.yml</code> triggerable from release)</li><li>[ ] Pro license public key is embedded or injectable in Pro builds (see <code>internal/license/keys_pro.go</code>)</li></ul>',25)])])}const u=t(i,[["render",l]]);export{p as __pageData,u as default};
